const COMPANION_NAMES = Object.keys(COMPANION_DATA);
// ===== Custom Library Item Interactivity =====
// A library entry may carry an `interactive` object describing how it should render
// on the character sheet once added. All sub-fields are optional and combinable:
//   interactive: {
//     activation: "action" | "bonus action" | "reaction" | "free",
//     uses:     { max: 3, resetOn: "dawn" | "shortRest" | "longRest" | "turn" },
//     roll:     { dice: "2d6", bonus: 0, type: "fire" | "healing" | "radiant" | ... },
//     duration: { total: 10, unit: "sec" | "min" | "hr" },
//     toggle:   { onLabel: "Activate", offLabel: "Deactivate" }
//   }
// Runtime state lives in char.libItemState[entry.id] = {usesUsed, active}.
// Duration piggybacks on the existing char.durationCounters/durationTimers keyed by "libitem-"+entry.id.
function resetLibItemUses(char, libEntries, restType){
  const state = {...(char.libItemState||{})};
  let changed = false;
  (libEntries||[]).forEach(e=>{
    const itv = e.interactive;
    if(!itv || !itv.uses) return;
    const resetOn = itv.uses.resetOn || "longRest";
    const matches = restType==="long" ? (resetOn==="shortRest"||resetOn==="longRest"||resetOn==="dawn") : restType==="short" ? resetOn==="shortRest" : false;
    if(matches && state[e.id] && state[e.id].usesUsed){
      state[e.id] = {...state[e.id], usesUsed:0};
      changed = true;
    }
  });
  return changed ? state : char.libItemState;
}
function LibItemCard({entry, char, setF, setCharSaving, setSkillRoll, openFeat, setOpenFeat}){
  const itv = entry.interactive;
  if(!itv) return null;
  const state = (char.libItemState && char.libItemState[entry.id]) || {usesUsed:0, active:false};
  const hasUses = itv.uses && itv.uses.max>0;
  const hasRoll = itv.roll && itv.roll.dice;
  const hasDuration = itv.duration && itv.duration.total>0;
  const hasToggle = !!itv.toggle;
  const usesLeft = hasUses ? Math.max(0, itv.uses.max-(state.usesUsed||0)) : null;
  const durId = "libitem-"+entry.id;

  const updateState = patch => setCharSaving(p=>({...p, libItemState:{...(p.libItemState||{}), [entry.id]:{...state, ...patch}}}));
  const startDuration = () => { if(hasDuration) setF("durationTimers",{...(char.durationTimers||{}),[durId]:{startedAt:Date.now(),baseRemaining:itv.duration.total}}); };
  const stopDuration = () => { if(!hasDuration) return; const nt={...(char.durationTimers||{})}; delete nt[durId]; setF("durationTimers",nt); };

  const doRoll = () => {
    const m=(itv.roll.dice||"").match(/(\d+)d(\d+)/i);
    const count=m?parseInt(m[1]):1, sides=m?parseInt(m[2]):6;
    const rolls=Array.from({length:count},()=>Math.floor(Math.random()*sides)+1);
    const bonus=itv.roll.bonus||0, total=rolls.reduce((a,b)=>a+b,0)+bonus, dmgType=itv.roll.type||"";
    setSkillRoll({label:entry.title+" ("+itv.roll.dice+(bonus?(bonus>0?"+"+bonus:bonus):"")+")",roll:rolls[0],bonus,total,isCrit:false,isFail:false,sides,r1:rolls[0],r2:rolls[1]||null,isAdv:false,isDis:false,isWeaponRoll:false,isSpellDmg:true,dmgTotal:total,allDmgRolls:rolls,dmgRolls:rolls,dmgBonus:bonus,dmgType,dmgDice:itv.roll.dice,diceSides:sides,baseDiceCount:count,saveDC:null,saveType:null,spiritShield:false});
    if(hasUses) updateState({usesUsed:(state.usesUsed||0)+1});
    if(hasDuration) startDuration();
  };
  const doToggle = () => {
    const turningOn=!state.active;
    if(turningOn && hasUses && usesLeft<=0) return;
    if(turningOn){ updateState({active:true, usesUsed:hasUses?(state.usesUsed||0)+1:state.usesUsed}); startDuration(); }
    else { updateState({active:false}); stopDuration(); }
  };
  const doUseOnly = () => { if(usesLeft<=0) return; updateState({usesUsed:(state.usesUsed||0)+1}); startDuration(); };
  const doResetUses = () => updateState({usesUsed:0});

  const color = hasRoll ? dmgTypeColor(itv.roll.type) : {bg:"rgba(99,102,241,0.08)",border:"rgba(99,102,241,0.3)",fg:"var(--accent)"};

  return (
    <div style={{background:"var(--input)",border:"1px solid var(--border)",borderRadius:8,padding:"8px 10px",marginTop:6}}>
      <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:(hasDuration||entry.desc)?4:0}}>
        <div style={{fontSize:10,fontWeight:700,color:"var(--accent)",letterSpacing:".05em",textTransform:"uppercase"}}>
          {entry.title}{itv.activation?" — "+itv.activation:""}
        </div>
        {hasDuration && <DurationBadge id={durId} short={itv.duration.total+" "+itv.duration.unit} full={"Duration: "+itv.duration.total+" "+itv.duration.unit+"."} total={itv.duration.total} unit={itv.duration.unit} openFeat={openFeat} setOpenFeat={setOpenFeat} char={char} setF={setF}/>}
      </div>
      {entry.desc && <div style={{fontSize:11,color:"var(--text)",lineHeight:1.5,marginBottom:6}}>{entry.desc}</div>}
      {hasUses && (
        <div style={{display:"flex",alignItems:"center",gap:6,marginBottom:6,flexWrap:"wrap"}}>
          <span style={{fontSize:10,fontWeight:700,color:"var(--muted)",textTransform:"uppercase",letterSpacing:".05em"}}>Uses ({usesLeft}/{itv.uses.max})</span>
          <div style={{display:"flex",gap:4}}>
            {Array.from({length:itv.uses.max},(_,i)=>{
              const spent=i<(state.usesUsed||0);
              return <div key={i} style={{width:14,height:14,borderRadius:"50%",border:"2px solid "+(spent?"var(--border)":"var(--accent)"),background:spent?"var(--input)":"rgba(99,102,241,0.15)"}}/>;
            })}
          </div>
          <span style={{fontSize:9,color:"var(--subtle)",fontStyle:"italic"}}>resets: {itv.uses.resetOn||"long rest"}</span>
        </div>
      )}
      <div style={{display:"flex",justifyContent:"flex-end",alignItems:"center",gap:6,flexWrap:"wrap"}}>
        {hasUses && (state.usesUsed>0) && <button onClick={doResetUses} style={{fontSize:9,color:"var(--subtle)",background:"none",border:"none",cursor:"pointer",fontFamily:"inherit"}}>↺ Reset</button>}
        {hasRoll ? (
          <button disabled={hasUses&&usesLeft<=0} onClick={doRoll}
            style={{fontSize:10,fontWeight:700,padding:"3px 10px",borderRadius:6,border:"1px solid "+color.border,background:color.bg,color:color.fg,cursor:(hasUses&&usesLeft<=0)?"not-allowed":"pointer",opacity:(hasUses&&usesLeft<=0)?0.4:1,fontFamily:"inherit"}}>
            🎲 Roll {itv.roll.dice}{itv.roll.type?" "+itv.roll.type:""}
          </button>
        ) : hasToggle ? (
          <button disabled={!state.active&&hasUses&&usesLeft<=0} onClick={doToggle}
            style={{fontSize:10,fontWeight:700,padding:"3px 10px",borderRadius:6,border:"1px solid "+(state.active?"rgba(239,68,68,0.3)":"rgba(34,197,94,0.3)"),background:state.active?"rgba(239,68,68,0.08)":"rgba(34,197,94,0.08)",color:state.active?"var(--red)":"var(--green)",cursor:(!state.active&&hasUses&&usesLeft<=0)?"not-allowed":"pointer",opacity:(!state.active&&hasUses&&usesLeft<=0)?0.4:1,fontFamily:"inherit"}}>
            {state.active?(itv.toggle.offLabel||"Deactivate"):(itv.toggle.onLabel||"Activate")}
          </button>
        ) : hasUses ? (
          <button disabled={usesLeft<=0} onClick={doUseOnly}
            style={{fontSize:10,fontWeight:700,padding:"3px 10px",borderRadius:6,border:"1px solid rgba(34,197,94,0.3)",background:usesLeft>0?"rgba(34,197,94,0.08)":"var(--input)",color:usesLeft>0?"var(--green)":"var(--muted)",cursor:usesLeft>0?"pointer":"not-allowed",fontFamily:"inherit"}}>
            ✓ Use
          </button>
        ) : null}
      </div>
    </div>
  );
}
function parseCompanionStatsFromNotes(notes){
  if(!notes) return null;
  const ac=notes.match(/AC:\s*(\d+)/i);
  const hp=notes.match(/HP:\s*(\d+)/i);
  const speed=notes.match(/Speed:\s*([^.]+)\./i);
  const stats=notes.match(/STR\s*(\d+)\s*DEX\s*(\d+)\s*CON\s*(\d+)\s*INT\s*(\d+)\s*WIS\s*(\d+)\s*CHA\s*(\d+)/i);
  if(!ac&&!hp&&!speed&&!stats) return null;
  return {
    ac: ac?ac[1]:"", hp: hp?hp[1]:"", speed: speed?speed[1].trim():"",
    STR: stats?parseInt(stats[1]):10, DEX: stats?parseInt(stats[2]):10, CON: stats?parseInt(stats[3]):10,
    INT: stats?parseInt(stats[4]):10, WIS: stats?parseInt(stats[5]):10, CHA: stats?parseInt(stats[6]):10,
  };
}
// Filters a class's per-level features table down to only levels the character has reached,
// and collapses level-progression variants of the same feature (e.g. "Extra Attack" / "Extra Attack (2)" /
// "Extra Attack (3)", or "Action Surge (1/rest)" / "Action Surge (2/rest)") to just the highest-level one reached.
function levelGatedFeatures(features, curLevel){
  const byBase = {};
  Object.entries(features||{}).forEach(([lvlStr, feats])=>{
    const lvl = Number(lvlStr);
    if(lvl>curLevel) return;
    (feats||[]).forEach(f=>{
      const base = f.split("(")[0].trim();
      if(!byBase[base] || byBase[base].lvl<=lvl) byBase[base]={lvl, full:f};
    });
  });
  return Object.values(byBase).map(v=>v.full);
}
function dmgTypeColor(type){
  const t=(type||"").toLowerCase();
  if(/heal/.test(t)) return {bg:"rgba(34,197,94,0.08)",border:"rgba(34,197,94,0.3)",fg:"var(--green)"};
  if(/reduction|temp hp|\bbonus\b/.test(t)) return {bg:"rgba(99,102,241,0.08)",border:"rgba(99,102,241,0.3)",fg:"var(--accent)"};
  if(/fire|radiant/.test(t)) return {bg:"rgba(249,115,22,0.08)",border:"rgba(249,115,22,0.3)",fg:"#f97316"};
  if(/cold|lightning|thunder/.test(t)) return {bg:"rgba(59,130,246,0.08)",border:"rgba(59,130,246,0.3)",fg:"#3b82f6"};
  if(/necrotic|poison|acid/.test(t)) return {bg:"rgba(167,139,250,0.08)",border:"rgba(167,139,250,0.3)",fg:"#a78bfa"};
  if(/force|psychic/.test(t)) return {bg:"rgba(236,72,153,0.08)",border:"rgba(236,72,153,0.3)",fg:"#ec4899"};
  return {bg:"rgba(239,68,68,0.08)",border:"rgba(239,68,68,0.3)",fg:"var(--red)"};
}

