                                    const pb=profBonus(char.level||1);
                                    const hasDexProf=(char.savingThrowProfs||[]).includes("DEX")||(CLASSES[char.charClass]?.savingThrows||[]).includes("DEX");
                                    const bonus=dexMod+(hasDexProf?pb:0);
                                    const total=roll+bonus;
                                    setSkillRoll({label:"DEX Save (Adv)",roll,bonus,total,isCrit:roll===20,isFail:false,sides:20,r1,r2,isAdv:true,isDis:false});
