 return(<button key={stat} onClick={()=>{if(fu2)return;setF("halfElfBonusStats",ch2?(char.halfElfBonusStats||[]).filter(s=>s!==stat):[...(char.halfElfBonusStats||[]),stat]);}} style={{padding:"4px 12px",borderRadius:8,fontSize:12,fontWeight:700,border:"1px solid "+(ch2?"rgba(34,197,94,0.5)":fu2?"var(--divider)":"var(--border)"),background:ch2?"rgba(34,197,94,0.1)":fu2?"transparent":"var(--input)",color:ch2?"var(--green)":fu2?"var(--subtle)":"var(--text)",cursor:fu2?"default":"pointer",fontFamily:"inherit"}}>{stat}{ch2&&" +1"}</button>);
