 const isAlwaysNotable = ALWAYS_NOTABLE.some(n=>feat.toLowerCase().startsWith(n.toLowerCase()));
 const hasContent = libFeat || det || isAlwaysNotable;
 if(!hasContent) return null;
 // Find which level this feature was unlocked
 const featLevel = Object.entries(cls.features).find(([,feats])=>feats.some(f=>f.split("(")[0].trim()===feat))?.[0];
 const ordinals = {1:"1st",2:"2nd",3:"3rd",4:"4th",5:"5th",6:"6th",7:"7th",8:"8th",9:"9th",10:"10th",11:"11th",12:"12th",13:"13th",14:"14th",15:"15th",16:"16th",17:"17th",18:"18th",19:"19th",20:"20th"};
 const levelLabel = featLevel&&Number(featLevel)>1 ? ordinals[Number(featLevel)]||featLevel+"th" : null;
 const key = `clf-${idx}`;
 const isOpen = openTrait(key);
 const isPrimalPath = feat==="Primal Path" && char.charClass==="Barbarian";
