 const hasDuelingStyle=char.classFightingStyle==="Dueling"||char.fiStyle==="Dueling"||char.championExtraStyle==="Dueling"||(char.charClass==="Bard"&&char.bardCollege==="College of Swords (Bard)"&&char.bardFightingStyle==="dueling");
 const hasOffhandWeaponG=(char.weaponItems||[]).some(i=>typeof i==="object"&&i.equipped&&i.name&&i.hand==="LH"&&i.name!==name);
