                                                    setSkillRoll({label:"Order's Wrath (2d8)",roll:rolls[0],bonus:0,total,isCrit:false,isFail:false,sides:8,r1:rolls[0],r2:null,isAdv:false,isDis:false,isWeaponRoll:false,isSpellDmg:true,dmgTotal:total,allDmgRolls:rolls,dmgRolls:rolls,dmgBonus:0,dmgType:"psychic",dmgDice:"2d8",diceSides:8,baseDiceCount:2,saveDC:null,saveType:null,spiritShield:false});
