                                              const wsLeftR=wsMaxR-wsUsedR;
                                              const wsLvlR=char.multiClassLevel>0?char.classLevel:char.level||1;
                                              const wsPbR=Math.ceil(1+wsLvlR/4);
                                              const wsWisModR=Math.floor(((char.abilities?.WIS||10)-10)/2);
                                              const wsSaveDC=8+wsPbR+wsWisModR;
